import { useState, useEffect } from 'react';
import axios from '../api/axios';

const TreatmentPlanner = ({ userId, onTreatmentPlan }) => {
  const [procedures, setProcedures] = useState([]);
  const [plan, setPlan] = useState({
    title: '',
    procedures: [],
    progress: 0,
  });
  const [selectedProcedure, setSelectedProcedure] = useState('');
  const [selectedDate, setSelectedDate] = useState('');

  // --- загрузка доступных процедур ---
  useEffect(() => {
    axios.get('/procedures')
      .then(res => setProcedures(res.data))
      .catch(err => console.error(err));
  }, []);

  // --- добавление процедуры в план ---
  const addProcedure = () => {
    if (!selectedProcedure || !selectedDate) return;
    setPlan(prev => ({
      ...prev,
      procedures: [
        ...prev.procedures,
        { procedureId: selectedProcedure, plannedDateUtc: new Date(selectedDate).toISOString(), done: false }
      ]
    }));
    setSelectedProcedure('');
    setSelectedDate('');
  };

  // --- удаление процедуры ---
  const removeProcedure = (index) => {
    setPlan(prev => ({
      ...prev,
      procedures: prev.procedures.filter((_, i) => i !== index)
    }));
  };

  // --- отправка плана на сервер ---
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('/plans', { ...plan, clientId: userId });
      onTreatmentPlan && onTreatmentPlan(res.data); // обработчик
      setPlan({ title: '', procedures: [], progress: 0 });
      alert('План курса успешно создан!');
    } catch (err) {
      alert(err.response?.data?.error || 'Ошибка создания плана');
    }
  };

  return (
    <div className="treatment-planner">
      <h2>📝 Планирование курса процедур</h2>
      <form onSubmit={handleSubmit}>
        {/* Название курса */}
        <input
          type="text"
          placeholder="Название курса"
          value={plan.title}
          onChange={e => setPlan({ ...plan, title: e.target.value })}
          required
        />

        {/* Выбор процедуры + дата */}
        <div className="form-actions">
          <select value={selectedProcedure} onChange={e => setSelectedProcedure(e.target.value)}>
            <option value="">Выберите процедуру</option>
            {procedures.map(p => (
              <option key={p._id} value={p._id}>{p.name}</option>
            ))}
          </select>

          <input
            type="date"
            value={selectedDate}
            onChange={e => setSelectedDate(e.target.value)}
          />

          <button type="button" onClick={addProcedure}>➕ Добавить процедуру</button>
        </div>

        {/* Список процедур */}
        <ul>
          {plan.procedures.map((proc, idx) => {
            const p = procedures.find(pr => pr._id === proc.procedureId);
            return (
              <li key={idx}>
                {p?.name} — {new Date(proc.plannedDateUtc).toLocaleDateString()}
                <button type="button" onClick={() => removeProcedure(idx)}>✖</button>
              </li>
            );
          })}
        </ul>

        {/* Прогресс */}
        <input
          type="number"
          min="0"
          max="100"
          placeholder="Прогресс (%)"
          value={plan.progress}
          onChange={e => setPlan({ ...plan, progress: e.target.value })}
        />

        <button type="submit">Создать курс</button>
      </form>
    </div>
  );
};

export default TreatmentPlanner;
